class Solution {
public:
    int numTrees(int n) {
        vector<int> dp(n + 1, 0);
        dp[0] = 1;
        dp[1] = 1;
        for (int len = 2; len <= n; len++) {
            for (int root = 1; root <= len; root++) {
                dp[len] += dp[root - 1] * dp[len - root];
            }
        }
        return dp[n];
    }
};

class Solution {
    public int numTrees(int n) {
        int[] dp = new int[n + 1];
        dp[0] = 1;
        dp[1] = 1;
        for (int len = 2; len <= n; len++) {
            for (int root = 1; root <= len; root++) {
                dp[len] += dp[root - 1] * dp[len - root];
            }
        }
        return dp[n];
    }
}

var numTrees = function(n) {
    const dp = new Array(n + 1).fill(0);
    dp[0] = 1;
    dp[1] = 1;
    for (let len = 2; len <= n; len++) {
        for (let root = 1; root <= len; root++) {
            dp[len] += dp[root - 1] * dp[len - root];
        }
    }
    return dp[n];
};
